Here is the root cause:
The bug was caused by the use of a static reference to `XE_FW_GT` for reading the RING_TIMESTAMP, which led to incorrect values (specifically zero) being returned when testing on certain engines. This was due to the fact that the firmware domain for each engine can vary, and using a generic reference did not account for these differences.

Here is the patch:

 static void show_run_ticks(struct drm_printer *p, struct drm_file *file)
 {
 	unsigned long class, i, gt_id, capacity[XE_ENGINE_CLASS_MAX] = { };
 	struct xe_file *xef = file->driver_priv;
 	struct xe_device *xe = xef->xe;
 	struct xe_gt *gt;
 	struct xe_hw_engine *hwe;
 	struct xe_exec_queue *q;
 	u64 gpu_timestamp;

 	xe_pm_runtime_get(xe);

 	/* Accumulate all the exec queues from this client */
 	mutex_lock(&xef->exec_queue.lock);
 	xa_for_each(&xef->exec_queue.xa, i, q) {
 		xe_exec_queue_update_run_ticks(q);
 		xef->run_ticks[q->class] += q->run_ticks - q->old_run_ticks;
 		q->old_run_ticks = q->run_ticks;
 	}
 	mutex_unlock(&xef->exec_queue.lock);

 	/* Get the total GPU cycles */
 	for_each_gt(gt, xe, gt_id) {
+		enum xe_force_wake_domains fw;
+
 		hwe = xe_gt_any_hw_engine(gt);
 		if (!hwe)
 			continue;

-		if (xe_force_wake_get(gt_to_fw(gt), XE_FW_GT)) {
+		fw = xe_hw_engine_to_fw_domain(hwe);
+		if (xe_force_wake_get(gt_to_fw(gt), fw)) {
 			hwe = NULL;
 			break;
 		}

 		gpu_timestamp = xe_hw_engine_read_timestamp(hwe);
-		XE_WARN_ON(xe_force_wake_put(gt_to_fw(gt), XE_FW_GT));
+		XE_WARN_ON(xe_force_wake_put(gt_to_fw(gt), fw));
 		break;
 	}

 	xe_pm_runtime_put(xe);

 	if (unlikely(!hwe))
 		return;

 	for (class = 0; class < XE_ENGINE_CLASS_MAX; class++) {
 		const char *class_name;

 		for_each_gt(gt, xe, gt_id)
 			capacity[class] += gt->user_engines.instances_per_class[class];

 		/*
 		 * Engines may be fused off or not exposed to userspace. Don't
 		 * return anything if this entire class is not available
 		 */
 		if (!capacity[class])
 			continue;

 		class_name = xe_hw_engine_class_to_str(class);
 		drm_printf(p, "drm-cycles-%s:\t%llu\n",
 			   class_name, xef->run_ticks[class]);
 		drm_printf(p, "drm-total-cycles-%s:\t%llu\n",
 			   class_name, gpu_timestamp);

 		if (capacity[class] > 1)
 			drm_printf(p, "drm-engine-capacity-%s:\t%lu\n",
 				   class_name, capacity[class]);
 	}
 }



